import 'package:flutter/material.dart';
class BlockUserDialog extends StatelessWidget{const BlockUserDialog({super.key,required this.name,required this.onConfirm});final String name;final VoidCallback onConfirm;@override Widget build(BuildContext context)=>AlertDialog(title:Text('Bloquear $name?'),content:const Text('Este usuário deixará de aparecer nas suas recomendações e interações sociais.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancelar')),FilledButton(onPressed:(){Navigator.pop(context);onConfirm();},child:const Text('Bloquear'))]);}
